12	const execFileAsync = promisify(execFile);
13	const STILL_BATCH_SIZE = 4;
14	const DURATION_FLOOR_SEC = 20;
15	
16	// Task 8 (not merged into this worktree) owns `GroundArtifact`/`VoiceArtifact`; these mirror the
17	// shapes documented in the plan's Task 8 Interfaces for the two fields this stage actually reads.
18	interface ReviewGroundInput {
19	  storyboard: Storyboard;
20	}
21	interface ReviewVoiceInput {
22	  audioPath: string | null;
23	  timings: LineTiming[];
24	}
25	
26	export function durationFinding(actualSec: number, targetSec: number): Finding | null {
27	  if (actualSec > targetSec * 1.25) {
28	    return {
29	      sceneId: null,
30	      issue: `reel runs ${actualSec.toFixed(1)}s, more than 25% over the ${targetSec}s target`,
31	      severity: 'high',
32	      fix: 'shorten narration lines or drop a scene',
33	    };
34	  }
35	  if (actualSec < DURATION_FLOOR_SEC) {
36	    return {
37	      sceneId: null,
38	      issue: `reel runs ${actualSec.toFixed(1)}s, under the ${DURATION_FLOOR_SEC}s floor`,
39	      severity: 'high',
40	      fix: 'add scenes or narration',
41	    };
42	  }
43	  return null;
44	}
45	
46	async function runFfmpegStderr(args: string[]): Promise<string> {
47	  try {
48	    const { stderr } = await execFileAsync('ffmpeg', args, { maxBuffer: 16 * 1024 * 1024 });
49	    return stderr;
50	  } catch (err) {
51	    return (err as { stderr?: string }).stderr ?? '';
52	  }
53	}
54	
55	async function blackFindings(videoPath: string): Promise<Finding[]> {
56	  const stderr = await runFfmpegStderr(['-i', videoPath, '-vf', 'blackdetect=d=0.5', '-an', '-f', 'null', '-']);
57	  const findings: Finding[] = [];
58	  for (const m of stderr.matchAll(/black_start:([\d.]+) black_end:([\d.]+) black_duration:([\d.]+)/g)) {
59	    const start = Number(m[1]);
60	    if (start > 1) {
61	      findings.push({
62	        sceneId: null,
63	        issue: `black frames from ${m[1]}s to ${m[2]}s (${m[3]}s)`,
64	        severity: 'high',
65	        fix: 'investigate the render for the scene at that timestamp',
66	      });
67	    }
68	  }
69	  return findings;
70	}
71	
72	async function silenceFindings(audioPath: string | null): Promise<Finding[]> {
73	  if (audioPath === null) return [];
74	  const gaps = await detectSilences(audioPath, { minSec: 1.8 });
75	  return gaps.map((g) => ({
76	    sceneId: null,
77	    issue: `silent gap from ${g.start.toFixed(1)}s to ${g.end.toFixed(1)}s in the narration`,
78	    severity: 'low' as const,
79	    fix: 'tighten the pause or re-time the line',
80	  }));
81	}
82	
83	function toDataUrl(path: string): string {
84	  return `data:image/png;base64,${readFileSync(path).toString('base64')}`;
85	}
86	
87	// A bare array, not `{ findings: [...] }`: validating that shape takes a zod object schema built
88	// with `z.object`, and this package has no direct dependency on `zod` to build one with (only
